import { readFileSync } from "node:fs"
import { describe, expect, it } from "vitest"

import { runtime } from "../src/internal.ts"

// Generated by crates/kirana_ir/tests/properties.rs from the build-time merge (KRN-TEST-003).
type Vector = {
  inputs: string[]
  markers: string[]
  atoms: string[]
  dom: string[]
}

const vectors = JSON.parse(
  readFileSync(
    new URL("../../../fixtures/merge/vectors.json", import.meta.url),
    "utf8"
  )
) as Vector[]

const k = runtime("k", "className")

// Markers keep first-applied order but the compiler writes them ahead of the merge table, so the
// two sequences are compared separately.
const partition = (classes: string) => {
  const tokens = classes.split(" ").filter(Boolean)
  return {
    markers: tokens.filter((token) => !token.includes("_")),
    atoms: tokens.filter((token) => token.includes("_")),
  }
}

describe("KRN-TEST-003 runtime merge matches the build-time merge", () => {
  it("has vectors", () => {
    expect(vectors.length).toBeGreaterThan(200)
  })

  it.each(vectors.map((vector, index) => [index, vector] as const))(
    "vector %i",
    (_, vector) => {
      const merged = partition(k.cx(vector.inputs) as string)
      expect(merged.atoms).toEqual(vector.atoms)
      expect(merged.markers).toEqual(vector.markers)
      const className = k.sx(vector.inputs, [], []).className as
        | string
        | undefined
      expect(partition(className ?? "").atoms).toEqual(vector.dom)
    }
  )
})
